// Standalone model check. Compile with BattleMap.cs and CreatureProfile.cs.
// Minimal Unity value-type substitutes allow checks without launching the Unity Editor.
using System;
namespace UnityEngine {
 public struct Vector2Int {
 public int x,y;public Vector2Int(int x,int y){this.x=x;this.y=y;}public static Vector2Int zero=>new Vector2Int(0,0);
 public static float Distance(Vector2Int a,Vector2Int b)=>(float)Math.Sqrt((double)(a.x-b.x)*(a.x-b.x)+(double)(a.y-b.y)*(a.y-b.y));
 public static bool operator ==(Vector2Int a,Vector2Int b)=>a.x==b.x&&a.y==b.y;public static bool operator !=(Vector2Int a,Vector2Int b)=>!(a==b);
 public override bool Equals(object o)=>o is Vector2Int&&this==(Vector2Int)o;public override int GetHashCode()=>x*31+y;
 }
 public static class Mathf {public static int RoundToInt(float n)=>(int)Math.Round(n,MidpointRounding.ToEven);}
}
class FootprintChecks {
static void Check(bool v,string n){if(!v)throw new Exception(n);}
static UnityEngine.Vector2Int V(int x,int y)=>new UnityEngine.Vector2Int(x,y);
static void Main(){var m=new BattleMap();Check(m.TrySetFootprint(false,2)&&m.Monster==V(8,8),"large bounds relocation");Check(!m.Place(true,V(9,9))&&m.Place(true,V(7,8)),"large occupied collision");Check(m.DistanceFeet==5,"nearest occupied-cell distance");Check(m.DistanceToCell(false,V(9,9))==0,"sphere includes far occupied cell");Check(!m.Place(false,V(9,8)),"footprint must fit board");Check(m.Lock()&&!m.TrySetFootprint(false,3),"locked footprint");m.Unlock();Check(m.TrySetFootprint(false,3)&&m.Inside(m.Monster,3),"huge resize");Check(!m.TrySetFootprint(false,5),"invalid footprint");m.Select(0);Check(m.Place(false,V(2,0))&&m.Place(true,V(0,0))&&m.Lock(),"path setup");Check(!m.CanMoveTo(V(5,0)),"swept path cannot cross occupied body");Check(m.CanMoveTo(V(0,4))&&m.MovePlayer(V(0,4))&&m.MovementRemaining==10,"cumulative movement cost");Check(!m.CanMoveTo(V(0,7)),"movement limit");Check(BattleMap.BodyDistance(V(0,0),2,V(2,2),2)==7,"large diagonal distance");Check(BattleMap.LeavesReach(V(3,0),V(5,0),V(0,0),5,1,3),"leave huge defender edge");Check(!BattleMap.LeavesReach(V(3,0),V(3,1),V(0,0),5,1,3),"stay within edge reach");Check(BattleMap.LeavesReach(V(1,1),V(2,2),V(0,0),7,1,1),"rounded diagonal reach");Check(CreatureProfile.SpacesForSize(2)==1&&CreatureProfile.SpacesForSize(3)==2&&CreatureProfile.SpacesForSize(4)==3&&CreatureProfile.SpacesForSize(5)==4,"size footprints");var forced=new BattleMap();forced.Place(false,V(7,0));forced.Lock();int budget=forced.MonsterMovementRemaining;Check(forced.ForceMoveAway(false,V(0,0),1,10)==10&&forced.Monster==V(9,0),"forced movement full distance");Check(forced.MonsterMovementRemaining==budget,"forced movement costs no movement");Check(forced.ForceMoveAway(false,V(0,0),1,10)==0,"forced boundary stops without extra distance");forced.Unlock();forced.Select(0);forced.TrySetFootprint(false,2);forced.Place(false,V(7,0));forced.Lock();Check(forced.ForceMoveAway(false,V(0,0),1,10)==5&&forced.Monster==V(8,0),"large forced footprint clips at boundary");forced.Unlock();forced.TrySetFootprint(false,1);forced.Place(false,V(3,0));forced.Place(true,V(1,0));forced.Lock();Check(forced.ForceMoveAway(true,V(-2,0),1,10)==5&&forced.Player==V(2,0),"forced movement stops before another body");var dash=new BattleMap();dash.Place(false,V(2,0));dash.Lock();Check(dash.MovePlayer(V(0,6))&&dash.MovementRemaining==0,"exhaust initial speed");dash.Dash();Check(dash.MovementRemaining==30&&dash.DashesThisTurn==1,"dash adds speed after exhaustion");dash.SetPlayerSpeed(40);Check(dash.MovementRemaining==50,"speed modifiers affect dash allowance without refunding spent distance");dash.SetPlayerSpeed(40);Check(dash.MovementRemaining==50,"repeated speed sync never grants free movement");int spent=dash.MovementSpent,budgetBefore=dash.MovementRemaining;var origin=dash.RoundStartPlayer;Check(dash.TeleportPlayer(V(0,1),30)&&dash.MovementRemaining==budgetBefore&&dash.MovementSpent==spent&&dash.RoundStartPlayer==origin,"teleport preserves budget and round origin");Check(!dash.TeleportPlayer(V(2,0),30)&&!dash.TeleportPlayer(V(9,9),30),"teleport occupied and out of range rejected");dash.TeleportPlayer(V(0,0),30);Check(dash.TeleportPlayer(V(4,0),30),"teleport can cross occupied intervening cells");dash.Dash();Check(dash.MovementMaximum==120,"multiple dash actions stack current speed");dash.RefreshMovement();Check(dash.DashesThisTurn==0&&dash.MovementRemaining==40,"turn clears dash grants");var restore=new BattleMap();restore.Place(false,V(8,8));restore.Lock();Check(restore.CanRestoreMonsterFootprint(2)&&restore.RestoreMonsterFootprint(2)&&restore.Monster==V(8,8)&&restore.MonsterSpaces==2,"restore large body at original anchor");Check(!restore.RestoreMonsterFootprint(3)&&restore.Monster==V(8,8)&&restore.MonsterSpaces==2,"out of bounds restoration is atomic");restore.Unlock();restore.TrySetFootprint(false,1);restore.Place(false,V(8,8));restore.Place(true,V(9,8));restore.Lock();Check(!restore.CanRestoreMonsterFootprint(2)&&!restore.RestoreMonsterFootprint(2)&&restore.MonsterSpaces==1,"blocked original anchor must not relocate body");var healing=new BattleMap();healing.Select(2);healing.Place(false,V(18,0));Check(healing.DistanceFeet==90&&healing.DistanceToCell(true,V(12,0))==60&&healing.DistanceToCell(false,V(12,0))==30,"mass cure may reach creature beyond caster-to-target 60 feet using legal center");Console.WriteLine("PASS: footprints, bounds, resize, swept collisions, cumulative movement, body distances, area targeting and opportunity reach");}}
